                "limit": limits.MAX_BATCH_RESOURCES,
            },
        )

    items: list[tuple] = []
    schema_keys: set[tuple[str, str]] = set()
    asset_ids: set[str] = set()

    for i, entry in enumerate(resources):
        if not isinstance(entry, dict):
            _invalid("批量登记条目必须是对象", reason="entry_not_object", index=i)
        rtype = entry.get("type")
        if rtype == _SCHEMA_TYPE:
            name = entry.get("name")
            version = entry.get("version")
            if not isinstance(name, str) or not name:
                _invalid(
                    "schema 条目的 name 必须是非空字符串",
                    reason="invalid_name", index=i,
                )
            if not isinstance(version, str) or not version:
                _invalid(
                    "schema 条目的 version 必须是非空字符串",
                    reason="invalid_version", index=i,
