def _validate_structure(resources: Any) -> list[tuple]:
    """校验整批条目的结构、类型、命名、指针与批次内唯一性。

    成功时返回与输入同序的内部条目：
    ``("schema", name, version, document)`` /
    ``("asset", asset_id, name, kind, refs)``。
    """
    if not isinstance(resources, list):
        raise BatchRegistrationInvalid(
            "resources 必须是列表", details={"reason": "resources_not_list"}
        )
    if len(resources) > limits.MAX_BATCH_RESOURCES:
        raise BatchRegistrationTooLarge(
            f"批量登记资源总数不得超过 {limits.MAX_BATCH_RESOURCES}",
            details={
                "reason": "batch_too_large",
                "size": len(resources),
                "limit": limits.MAX_BATCH_RESOURCES,
            },
        )

    items: list[tuple] = []
    schema_keys: set[tuple[str, str]] = set()
    asset_ids: set[str] = set()

    for i, entry in enumerate(resources):
        if not isinstance(entry, dict):
            _invalid("批量登记条目必须是对象", reason="entry_not_object", index=i)
        rtype = entry.get("type")
        if rtype == _SCHEMA_TYPE:
            name = entry.get("name")
            version = entry.get("version")
            if not isinstance(name, str) or not name:
                _invalid(
                    "schema 条目的 name 必须是非空字符串",
                    reason="invalid_name", index=i,
                )
            if not isinstance(version, str) or not version:
                _invalid(
                    "schema 条目的 version 必须是非空字符串",
                    reason="invalid_version", index=i,
                )
            try:
                _validate_name(name, what="Schema 名称")
                _validate_name(version, what="版本号")
            except ValueError as exc:
                _invalid(str(exc), reason="invalid_name", index=i)
            if "document" not in entry:
                _invalid(
                    "schema 条目缺少必填字段 document",
                    reason="missing_document", index=i,
                )
            key = (name, version)
            if key in schema_keys:
                _invalid(
                    f"批次内 Schema {name}@{version} 重复",
                    reason="duplicate_schema", index=i,
                    schema=name, version=version,
                )
            schema_keys.add(key)
            items.append((_SCHEMA_TYPE, name, version, entry["document"]))

        elif rtype == _ASSET_TYPE:
            asset_id = entry.get("asset_id")
            name = entry.get("name")
            kind = entry.get("kind")
            if not isinstance(asset_id, str) or not asset_id:
                _invalid(
                    "asset 条目的 asset_id 必须是非空字符串",
                    reason="invalid_asset_id", index=i,
                )
            try:
                _validate_name(asset_id, what="资产标识")
            except ValueError as exc:
                _invalid(str(exc), reason="invalid_asset_id", index=i)
            if not isinstance(name, str) or not name:
                _invalid(
                    "asset 条目的 name 必须是非空字符串",
                    reason="invalid_asset_name", index=i,
                )
            if not isinstance(kind, str) or not kind:
                _invalid(
                    "asset 条目的 kind 必须是非空字符串",
                    reason="invalid_asset_kind", index=i,
                )
            if asset_id in asset_ids:
                _invalid(
                    f"批次内资产 {asset_id} 重复",
                    reason="duplicate_asset", index=i, asset=asset_id,
                )
            refs = entry.get("refs", [])
            if refs is None:
                refs = []
            if not isinstance(refs, list):
                _invalid(
                    "asset 条目的 refs 必须是列表",
                    reason="invalid_refs", index=i,
                )
            normalized_refs = _validate_refs(refs, i)
            asset_ids.add(asset_id)
            items.append((_ASSET_TYPE, asset_id, name, kind, normalized_refs))

        else:
            _invalid(
                "条目 type 必须是 schema 或 asset",
                reason="invalid_type", index=i, value=rtype,
            )

    return items


def _validate_refs(refs: list[Any], index: int) -> list[dict[str, str]]:
    """校验单个资产条目的 refs 结构与指针语法（不做存在性解析）。"""
    out: list[dict[str, str]] = []
    for j, raw in enumerate(refs):
        if not isinstance(raw, dict):
            _invalid(
                "资产 refs 每项必须是对象",
                reason="ref_not_object", index=index, ref_index=j,
            )
        schema = raw.get("schema")
        version = raw.get("version")
        if not isinstance(schema, str) or not schema:
            _invalid(
                "资产引用的 schema 必须是非空字符串",
                reason="invalid_ref_schema", index=index, ref_index=j,
            )
        if not isinstance(version, str) or not version:
            _invalid(
                "资产引用的 version 必须是非空字符串",
                reason="invalid_ref_version", index=index, ref_index=j,
            )
        try:
            _validate_name(schema, what="引用 Schema 名称")
        except ValueError as exc:
            _invalid(str(exc), reason="invalid_ref_schema", index=index, ref_index=j)
        path = raw.get("path", "")
        if path is None:
            path = ""
        if not isinstance(path, str):
            _invalid(
                "资产引用的 path 必须是字符串",
                reason="invalid_ref_path", index=index, ref_index=j,
            )
        if path and not path.startswith("/"):
            _invalid(
                f"资产引用字段路径必须是 JSON Pointer: {path!r}",
                reason="invalid_pointer", index=index, ref_index=j, path=path,
            )
        try:
            ptr.parse(path)
        except ValueError as exc:
            _invalid(
                f"资产引用字段路径不是合法 JSON Pointer: {path!r}",
                reason="invalid_pointer", index=index, ref_index=j, path=path,
            ) from exc
        if not _valid_pointer_escapes(path):
            _invalid(
                f"资产引用字段路径不是合法 JSON Pointer（~ 后只允许 0 或 1）: {path!r}",
                reason="invalid_pointer", index=index, ref_index=j, path=path,
            )
        out.append({"schema": schema, "version": version, "path": path})
    return out


def _valid_pointer_escapes(path: str) -> bool:
    """逐段检查 JSON Pointer 转义：``~`` 后只能是 ``0`` 或 ``1``。"""
    for segment in path.split("/")[1:] if path else ():
        k = 0
        while k < len(segment):
            if segment[k] == "~":
                if k + 1 >= len(segment) or segment[k + 1] not in "01":
                    return False
                k += 2
            else:
                k += 1
    return True


def _validate_documents(items: list[tuple]) -> None:
    """按输入顺序校验 Schema 文档合法性（SchemaComparisonInvalid）。"""
    for item in items:
        if item[0] == _SCHEMA_TYPE:
            _, name, version, document = item
            try:
                validate_schema(document)
            except SchemaComparisonInvalid as exc:
                exc.details.setdefault("schema", name)
                exc.details.setdefault("version", version)
                raise


